"""Exact changed-bound source inverse and independent raw40 count; no runtime equivalence."""
import hashlib,struct
OLD_SHA='ae129692f216a56af7abc075e7ca73e9fbc0922b3d6ea2fe1d84369ab2413e7f'
NEW_SHA='a6a09abd67c2ce7b96b3b84a71374f865a45d121e66820133c71107b7af5c564'
EDITS=[{'newLine': 193, 'newCount': 0, 'oldHex': '2020202020202020202020206966286261746368576f726473206973206e756c6c296275646765742e416464536f75726365286f776e65722e5265636f7264732e4c656e6774682f34302c636f6d70616374436f756e742c736f757263652e5265666572656e6365436f756e742c53636f70652e446f63756d656e742e4f626a656374436f756e74293b0d0a', 'newHex': ''}, {'newLine': 204, 'newCount': 4, 'oldHex': '', 'newHex': ''}]
def restore(raw):
    observed=hashlib.sha256(raw).hexdigest()
    if observed==OLD_SHA:return raw,None
    assert observed==NEW_SHA,'Unknown matching-bound source'
    lines=raw.splitlines(keepends=True)
    for edit in reversed(EDITS):
        start=edit['newLine'];chunk=b''.join(lines[start:start+edit['newCount']]);assert chunk==bytes.fromhex(edit['newHex'])
        lines[start:start+edit['newCount']]=bytes.fromhex(edit['oldHex']).splitlines(keepends=True)
    previous=b''.join(lines);assert hashlib.sha256(previous).hexdigest()==OLD_SHA
    assert raw.count(b'budget.AddSource(owner.Records.Length/40,matchingCompact,source.ReferenceCount,Scope.Document.ObjectCount);')==1
    assert b'if(batchWords is null)budget.AddSource' not in raw
    return previous,{'Policy':'MatchingCompactForSingletonAndBatch','ObservedRawSHA256':NEW_SHA,'HistoricalInverseRawSHA256':OLD_SHA,'InverseHunks':len(EDITS),'ChangedBudgetSemantics':True,'RuntimeEquivalenceClaim':False,'HistoricalProofViewOnly':True}
def matching_count(storage,starts,active,node,key):
    assert type(storage) is bytes and len(storage)%40==0
    assert type(active) is int and 0<active<=len(storage)//40
    assert type(starts) is list and len(starts)>=2 and starts[0]==0
    assert all(type(x) is int and 0<=x<=active for x in starts) and all(a<=b for a,b in zip(starts,starts[1:])) and starts[-1]==active
    assert type(node) is int and 0<=node<len(starts)-1 and type(key) is int and 0<=key<2**64
    return sum(bool(storage[i*40+32]&0x20) and (storage[i*40+32]&7)==0 and struct.unpack_from('<Q',storage,i*40+8)[0]==key for i in range(starts[node],starts[node+1]))
